  `id_nominas` int DEFAULT NULL,
  `id_desc_cred_nomina` int DEFAULT NULL,
  `estado` enum('pendiente','aplicado','cancelado') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'pendiente',
