--
-- Table structure for table `rh_empleado`
--

DROP TABLE IF EXISTS `rh_empleado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rh_empleado` (
  `id_empleado` int NOT NULL AUTO_INCREMENT,
  `cedula_empleado` varchar(45) NOT NULL,
  `nombres` varchar(100) DEFAULT NULL,
  `apellidos` varchar(100) DEFAULT NULL,
  `direccion` longtext,
  `telefono` varchar(45) DEFAULT NULL,
  `fecha_nac` date DEFAULT NULL,
  `id_ars` int DEFAULT NULL,
  `id_afp` int DEFAULT NULL,
  `tssnumero` varchar(100) DEFAULT NULL,
  `id_puesto` int DEFAULT NULL,
  `salario_act` decimal(10,2) DEFAULT NULL,
  `id_nomina` int DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  `fecha_ingreso` datetime DEFAULT NULL,
  `aquienllamaemergencia` longtext,
  `telefonoemergencia` varchar(45) DEFAULT NULL,
  `foto` longblob,
  `tipodesembolso` varchar(45) DEFAULT NULL,
  `licencia` tinyint(1) DEFAULT NULL,
  `id_ubicacion` int DEFAULT NULL,
  `id_subnomina` int DEFAULT NULL,
  `mail` varchar(100) DEFAULT NULL,
  `cuentabancario` varchar(100) DEFAULT NULL,
  `cuenta_contable` varchar(255) DEFAULT NULL,
  `id_banco` int DEFAULT NULL,
  PRIMARY KEY (`id_empleado`),
  UNIQUE KEY `cedula_empleado_UNIQUE` (`cedula_empleado`)
) ENGINE=InnoDB AUTO_INCREMENT=8224 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

