CREATE TABLE `rh_estado_empleado` (
  `id_estado_empleado` int NOT NULL AUTO_INCREMENT,
  `id_empleado` int NOT NULL,
  `estado` enum('activo','inactivo') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `fecha_efectiva` date NOT NULL,
  `id_tipo_despido` int DEFAULT NULL,
  `comentario` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `fecha_creacion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_estado_empleado`),
  KEY `id_empleado` (`id_empleado`),
  KEY `id_tipo_despido` (`id_tipo_despido`),
  CONSTRAINT `rh_estado_empleado_ibfk_1` FOREIGN KEY (`id_empleado`) REFERENCES `rh_empleado` (`id_empleado`),
  CONSTRAINT `rh_estado_empleado_ibfk_2` FOREIGN KEY (`id_tipo_despido`) REFERENCES `rh_tipo_despido` (`id_tipo_despido`)
) ENGINE=InnoDB AUTO_INCREMENT=497 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
