CREATE TABLE `sys_auditoria` (
  `id_auditoria` bigint NOT NULL AUTO_INCREMENT,
  `usuario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID del usuario autenticado',
  `nombre_completo` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nombre completo del usuario',
  `nivel_usuario` int DEFAULT NULL COMMENT 'Nivel de permisos (1-9)',
  `fecha_hora` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Timestamp con milisegundos',
  `modulo` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mâ”œâ”‚dulo del sistema (ej: EMPLEADOS, NOMINAS)',
  `accion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tipo de acciâ”œâ”‚n (ej: CREAR, MODIFICAR, ELIMINAR)',
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Descripciâ”œâ”‚n legible de la acciâ”œâ”‚n',
  `tabla_afectada` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nombre de la tabla principal afectada',
  `id_registro` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ID del registro afectado',
  `valores_anteriores` json DEFAULT NULL COMMENT 'Estado antes de la modificaciâ”œâ”‚n (UPDATE/DELETE)',
  `valores_nuevos` json DEFAULT NULL COMMENT 'Estado despuâ”œÂ®s de la modificaciâ”œâ”‚n (INSERT/UPDATE)',
  `ip_cliente` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Direcciâ”œâ”‚n IP del cliente (IPv4/IPv6)',
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Navegador/dispositivo del usuario',
  `metodo_http` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mâ”œÂ®todo HTTP (GET, POST, PUT, DELETE)',
  `url_endpoint` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ruta del endpoint llamado',
  `resultado` enum('EXITO','FALLO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EXITO' COMMENT 'Resultado de la operaciâ”œâ”‚n',
  `mensaje_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Mensaje de error si resultado = FALLO',
  PRIMARY KEY (`id_auditoria`),
  KEY `idx_usuario` (`usuario`),
  KEY `idx_fecha_hora` (`fecha_hora`),
  KEY `idx_modulo` (`modulo`),
  KEY `idx_accion` (`accion`),
  KEY `idx_tabla_id` (`tabla_afectada`,`id_registro`),
  KEY `idx_usuario_fecha` (`usuario`,`fecha_hora`),
  KEY `idx_resultado` (`resultado`)
) ENGINE=InnoDB AUTO_INCREMENT=1293 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla de auditorâ”œÂ¡a para registro de todas las actividades del sistema';
