CREATE TABLE `sys_sesiones_auditoria` (
  `id_sesion` bigint NOT NULL AUTO_INCREMENT,
  `usuario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID del usuario',
  `tipo_evento` enum('LOGIN','LOGOUT','TOKEN_EXPIRADO','SESION_INVALIDA') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tipo de evento de sesiâ”œâ”‚n',
  `fecha_hora` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Timestamp del evento',
  `ip_cliente` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Direcciâ”œâ”‚n IP del cliente',
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Navegador/dispositivo',
  `resultado` enum('EXITO','FALLO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Resultado del evento',
  `detalle_fallo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Detalle del fallo si aplica',
  PRIMARY KEY (`id_sesion`),
  KEY `idx_usuario_sesion` (`usuario`),
  KEY `idx_fecha_sesion` (`fecha_hora`),
  KEY `idx_tipo_evento` (`tipo_evento`)
) ENGINE=InnoDB AUTO_INCREMENT=421 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla de auditorâ”œÂ¡a para eventos de inicio/cierre de sesiâ”œâ”‚n';
