CREATE DEFINER=`root`@`%` FUNCTION `fn_tiene_historial_nomina`(
  p_id_empleado INT,
  p_anio YEAR
) RETURNS tinyint(1)
    READS SQL DATA
    DETERMINISTIC
BEGIN
  DECLARE v_count INT;

  SELECT COUNT(DISTINCT ndn.id_nomina)
  INTO v_count
  FROM no_det_nomina ndn
  INNER JOIN no_nominas n ON ndn.id_nomina = n.id_nominas
  WHERE ndn.id_empleado = p_id_empleado
    AND YEAR(n.fecha_nomina) = p_anio
    AND n.status = 0;  -- Solo nÃ³minas cerradas

  RETURN IF(v_count > 0, 1, 0);
END ;;
DELIMITER ;
