CREATE DEFINER=`root`@`%` FUNCTION `fn_total_salarios_importados`(
  p_id_empleado INT,
  p_anio YEAR
) RETURNS decimal(10,2)
    READS SQL DATA
    DETERMINISTIC
BEGIN
  DECLARE v_total DECIMAL(10,2);

  SELECT
    COALESCE(salario_enero, 0) +
    COALESCE(salario_febrero, 0) +
    COALESCE(salario_marzo, 0) +
    COALESCE(salario_abril, 0) +
    COALESCE(salario_mayo, 0) +
    COALESCE(salario_junio, 0) +
    COALESCE(salario_julio, 0) +
    COALESCE(salario_agosto, 0) +
    COALESCE(salario_septiembre, 0) +
    COALESCE(salario_octubre, 0) +
    COALESCE(salario_noviembre, 0)
  INTO v_total
  FROM no_regalia_historial_importado
  WHERE id_empleado = p_id_empleado
    AND anio = p_anio;

  RETURN COALESCE(v_total, 0);
END ;;
DELIMITER ;
