DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_calcular_regalia_sin_historial`(
  IN p_id_empleado INT,
  IN p_anio YEAR,
  OUT p_monto_calculado DECIMAL(10,2),
  OUT p_meses_laborados INT
)
BEGIN
  DECLARE v_fecha_ingreso DATE;
  DECLARE v_salario_actual DECIMAL(10,2);
  DECLARE v_fecha_inicio DATE;
  DECLARE v_fecha_fin DATE;
  DECLARE v_meses INT;

  -- Obtener datos del empleado
  SELECT fecha_ingreso, salario_act
  INTO v_fecha_ingreso, v_salario_actual
  FROM rh_empleado
  WHERE id_empleado = p_id_empleado;

  -- Definir rango del aÃ±o
  SET v_fecha_inicio = CONCAT(p_anio, '-01-01');
  SET v_fecha_fin = CONCAT(p_anio, '-12-31');

  -- Si ingresÃ³ despuÃ©s del inicio del aÃ±o, usar fecha de ingreso
  IF v_fecha_ingreso > v_fecha_inicio THEN
    SET v_fecha_inicio = v_fecha_ingreso;
  END IF;

  -- Calcular meses completos laborados
  SET v_meses = TIMESTAMPDIFF(MONTH, v_fecha_inicio, v_fecha_fin) + 1;

  -- Calcular regalÃ­a proporcional
  -- FÃ³rmula: (salario_actual * meses_laborados) / 12
  SET p_monto_calculado = (v_salario_actual * v_meses) / 12;
  SET p_meses_laborados = v_meses;

END ;;
DELIMITER ;
