CREATE DEFINER=`root`@`%` PROCEDURE `sp_limpiar_historial_antiguo`(
  IN p_anios_antiguedad INT
)
BEGIN
  DECLARE v_anio_limite YEAR;

  -- Calcular aÃ±o lÃ­mite (ej: si p_anios_antiguedad = 3, eliminar registros mayores a 3 aÃ±os)
  SET v_anio_limite = YEAR(CURDATE()) - p_anios_antiguedad;

  -- Eliminar historial antiguo
  DELETE FROM no_regalia_historial_importado
  WHERE anio < v_anio_limite;

  -- Eliminar logs antiguos
  DELETE FROM no_regalia_importacion_log
  WHERE anio < v_anio_limite;

  -- Retornar cantidad de registros eliminados
  SELECT ROW_COUNT() AS registros_eliminados;
END ;;
DELIMITER ;
